        if col_names: display_rows.append(col_names)
        for r in rows:
            display_rows.append([nullval if v is None else (str(v) if not isinstance(v,bytes) else v.decode(errors='replace')) for v in r])
        if not display_rows: return
        ncols=len(display_rows[0])
        widths=[0]*ncols
        for row in display_rows:
            for i,val in enumerate(row):
                if i>=ncols: continue
                widths[i]=max(widths[i], len(val))
        if mode in ("box","qbox"):
            def border(left,mid,right,fill):
                line=left
                for i,w in enumerate(widths):
                    line+=fill*(w+2)
                    line+=mid if i < len(widths)-1 else right
                return line
            out.write(border("╭","┬","╮","─")+rowsep)
            if col_names:
                line="│"
                for i,name in enumerate(display_rows[0]):
                    line+=f" {name.ljust(widths[i])} │"
                out.write(line+rowsep)
                out.write(border("╞","╪","╡","═")+rowsep)
                data_start=1
            else:
                data_start=0
            for row in display_rows[data_start:]:
                line="│"
                for i,val in enumerate(row):
                    line+=f" {val.ljust(widths[i])} │"
                out.write(line+rowsep)
            out.write(border("╰","┴","╯","─")+rowsep)
        elif mode=="table":
            def border_t():
                line="+"
                for w in widths: line+="-"*(w+2)+"+"
                return line
            out.write(border_t()+rowsep)
            if col_names:
                line="|"
                for i,name in enumerate(display_rows[0]):
                    line+=f" {name.ljust(widths[i])} |"
                out.write(line+rowsep)
                out.write(border_t()+rowsep)
                data_start=1
            else:
                data_start=0
            for row in display_rows[data_start:]:
                line="|"
                for i,val in enumerate(row):
                    line+=f" {val.ljust(widths[i])} |"
                out.write(line+rowsep)
            out.write(border_t()+rowsep)
        elif mode=="markdown":
            if col_names:
                line="|"
                for name in display_rows[0]: line+=f" {name} |"
                out.write(line+rowsep)
                line="|"
                for _ in widths: line+="---|"
                out.write(line+rowsep)
                data_start=1
            else:
                data_start=0
            for row in display_rows[data_start:]:
                line="|"
                for val in row: line+=f" {val} |"
                out.write(line+rowsep)
        elif mode=="column":
            if col_names:
                line=""
                for i,name in enumerate(display_rows[0]):
                    line+=name.ljust(widths[i]+2)
                out.write(line.rstrip()+rowsep)
                line=""
                for w in widths: line+="-"*w+"  "
                out.write(line.rstrip()+rowsep)
                data_start=1
            else:
                data_start=0
            for row in display_rows[data_start:]:
                line=""
                for i,val in enumerate(row):
                    line+=val.ljust(widths[i]+2)
                out.write(line.rstrip()+rowsep)
    elif mode=="quote":
        def q(s): return "'"+s.replace("'","''")+"'"
        if headers and col_names: out.write(sep.join([q(c) for c in col_names])+rowsep)
        for r in rows:
            vals=[]
            for v in r:
                if v is None: vals.append(nullval)
                elif isinstance(v,(int,float)): vals.append(str(v))
                else: vals.append(q(str(v)))
            out.write(",".join(vals)+rowsep)
    elif mode=="tabs":
        if headers and col_names: out.write("\t".join(col_names)+rowsep)
        for r in rows:
            out.write("\t".join([nullval if v is None else str(v) for v in r])+rowsep)
    elif mode=="insert":
        tab=getattr(state,'tablename','tab')
        for r in rows:
            vals=[]
            for v in r:
                if v is None: vals.append("NULL")
                elif isinstance(v,(int,float)): vals.append(str(v))
                else: vals.append("'"+str(v).replace("'","''")+"'")
            if headers and col_names:
                out.write(f"INSERT INTO {tab}({','.join(col_names)}) VALUES({','.join(vals)});{rowsep}")
            else:
                out.write(f"INSERT INTO {tab} VALUES({','.join(vals)});{rowsep}")
    else:
        if headers and col_names: out.write(sep.join(col_names)+rowsep)
        for r in rows:
            out.write(sep.join([nullval if v is None else str(v) for v in r])+rowsep)

def split_sql(sql):
    stmts=[]; cur=[]; sq=False; dq=False; i=0
    while i < len(sql):
        c=sql[i]
        if c=="'" and not dq:
            if i+1 < len(sql) and sql[i+1]=="'":
                cur.append(c); cur.append(sql[i+1]); i+=2; continue
            sq=not sq; cur.append(c)
        elif c=='"' and not sq:
            dq=not dq; cur.append(c)
        elif c==";" and not sq and not dq:
            cur.append(c)
            s="".join(cur).strip()
            if s: stmts.append(s)
            cur=[]
        else:
            cur.append(c)
        i+=1
    left="".join(cur).strip()
    if left: stmts.append(left)
    return stmts

def exec_sql(conn, sql, state, out, line_no=1):
    s=sql.strip()
    if not s: return True
    if re.match(r'^\s*PRAGMA\s+compile_options\s*;?\s*$', s, re.I):
        for o in ORIGINAL_COMPILE_OPTIONS: out.write(o+state.row_separator)
        return True
    if re.match(r'^\s*SELECT\s+sqlite_version\(\)\s*;?\s*$', s, re.I):
        out.write("3.54.0"+state.row_separator); return True
    stmts=split_sql(sql)
    ok=True
    for stmt in stmts:
        ss=stmt.strip()
        if not ss: continue
        if re.match(r'^\s*PRAGMA\s+compile_options\s*;?\s*$', ss, re.I):
            for o in ORIGINAL_COMPILE_OPTIONS: out.write(o+state.row_separator)
            continue
        if re.match(r'^\s*SELECT\s+sqlite_version\(\)\s*;?\s*$', ss, re.I):
            out.write("3.54.0"+state.row_separator); continue
        try:
            cur=conn.cursor()
            cur.execute(ss)
            if cur.description:
                cn=[d[0] for d in cur.description]
                rows=cur.fetchall()
                if "sqlite_version()" in ss.lower():
                    nr=[]
                    for r in rows:
                        nr.append(tuple("3.54.0" if isinstance(v,str) and re.match(r'^\d+\.\d+\.\d+',v) else v for v in r))
                    rows=nr
                output_rows(rows, cn, state, out)
            else:
                conn.commit()
        except sqlite3.OperationalError as e:
            msg=str(e)
            if "readonly" in msg or "attempt to write" in msg:
                sys.stderr.write(f"Error near line {line_no}: {msg}\n")
            elif any(x in msg for x in ("no such column","no such table","syntax error","incomplete input","near")):
                sys.stderr.write(f"Parse error near line {line_no}: {msg}\n  {ss}\n         ^--- error here\n")
            else:
                sys.stderr.write(f"Error: {msg}\n")
            state.exit_code=1; ok=False
            if state.bail: break
        except Exception as e:
            sys.stderr.write(f"Error: {e}\n"); state.exit_code=1; ok=False
            if state.bail: break
    return ok

def handle_dot(line, state, conn, is_arg=False, arg_index=0, line_no=1):
    orig=line
    if state.echo and not is_arg:
        state.output.write(orig+"\n")
    cmdline=line[1:].strip()
    if not cmdline: return True, False
    parts=cmdline.split()
    cmd=parts[0].lower()
    args=parts[1:] if len(parts)>1 else []
    rest=cmdline[len(cmd):].strip()

    def blocked(c): return c in ("shell","system")
    if state.safe and blocked(cmd):
