def process_input(lines, state, conn):
    buf=""; start=1; cur=1
    for raw in lines:
        line=raw.rstrip("\n")
        if state.echo and not line.strip().startswith("."):
            state.output.write(line+"\n")
        st=line.strip()
        if not st:
            if buf: buf+="\n"
            cur+=1; continue
        if st.startswith(".") and not buf.strip():
            cont,abort=handle_dot(st,state,conn,is_arg=False,line_no=cur)
            if abort: return conn, True
            if state.db is not None and state.db is not conn:
                try: conn.close()
                except: pass
                conn=state.db
            cur+=1; continue
        else:
            if not buf.strip(): start=cur
            buf+=line+"\n"
            try:
                if sqlite3.complete_statement(buf):
                    for s in split_sql(buf):
                        if not exec_sql(conn,s,state,state.output,line_no=start):
                            if state.bail: return conn, True
                    buf=""
            except: pass
        cur+=1
    if buf.strip():
        exec_sql(conn,buf,state,state.output,line_no=start)
    return conn, False

