                sys.stderr.write(f"{sys.argv[0]}: Error: unknown option: {arg}\nUse -help for a list of options.\n"); sys.exit(1)
        else:
            if db_filename is None: db_filename=arg
            else: sql_args.append(arg)
        i+=1

    if db_filename is None: db_filename=":memory:"
    if ifexists and db_filename!=":memory:" and not os.path.exists(db_filename):
        sys.stderr.write(f"Error: unable to open database \"{db_filename}\": unable to open database file\n"); sys.exit(1)

    init_files=[]
    if not noinit:
        rc=os.path.expanduser("~/.sqliterc")
        if os.path.exists(rc): init_files.append(rc)
    if init_file: init_files.append(init_file)

    try:
        if readonly:
            conn=sqlite3.connect(f"file:{db_filename}?mode=ro", uri=True)
        else:
            conn=sqlite3.connect(db_filename)
    except Exception as e:
        sys.stderr.write(f"Error: unable to open database \"{db_filename}\": {e}\n"); sys.exit(1)

    state.db=conn; state.db_filename=db_filename; state.readonly=readonly

    for fp in init_files:
        try:
            with open(fp,"r",encoding="utf-8",errors='replace') as f:
                content=f.read()
                conn,_=process_input(content.splitlines(), state, conn)
        except FileNotFoundError:
            sys.stderr.write(f"Error: cannot open \"{fp}\"\n")

    for cs in cmds:
        if cs.strip().startswith("."):
            _,abort=handle_dot(cs.strip(), state, conn, is_arg=False, line_no=1)
            if abort: sys.exit(state.exit_code)
            if state.db is not None and state.db is not conn:
                try: conn.close()
                except: pass
                conn=state.db
        else:
            exec_sql(conn, cs, state, state.output)

    if sql_args:
        for idx, sa in enumerate(sql_args):
            arg_num=2+idx
            def ords(n): return "1st" if n==1 else "2nd" if n==2 else "3rd" if n==3 else f"{n}th"
            try: ap=orig_argv.index(sa)
            except: ap=arg_num+2
            if sa.strip().startswith("."):
                _,abort=handle_dot(sa.strip(), state, conn, is_arg=True, arg_index=ap, line_no=1)
                if abort: sys.exit(state.exit_code)
                if state.db is not None and state.db is not conn:
                    try: conn.close()
                    except: pass
                    conn=state.db
            else:
                try:
                    cur=conn.cursor()
                    for stmt in split_sql(sa):
                        try:
                            cur.execute(stmt)
                            if cur.description:
                                rows=cur.fetchall()
                                output_rows(rows, [d[0] for d in cur.description], state, state.output)
                            else:
                                conn.commit()
                        except sqlite3.Error as e:
                            sys.stderr.write(f"Parse error in {ords(arg_num)} command line argument: {e}\n  {stmt}\n         ^--- error here\n")
                            sys.exit(1)
                except SystemExit: raise
                except Exception as e:
                    sys.stderr.write(f"Parse error in {ords(arg_num)} command line argument: {e}\n  {sa}\n         ^--- error here\n")
                    sys.exit(1)
        if state.output_file: state.output_file.close()
        sys.exit(state.exit_code)

    data=sys.stdin.read()
    if data:
        conn,trig=process_input(data.splitlines(), state, conn)
        if trig and state.output_file:
            state.output_file.close()
            sys.exit(state.exit_code)
    if state.output_file: state.output_file.close()
    sys.exit(state.exit_code)

if __name__=="__main__":
    main()
